FROM STUDENT JOIN ENROLL WITH(Sno)
WHERE ENROLL.Cno = 'C413';

② SELECT Sname, Dept, Grade
FROM STUDENT NATURAL JOIN ENROLL USING(Sno)
WHERE ENROLL.Cno = 'C413';

③ SELECT Sname, Dept, Grade
FROM STUDENT NATURAL JOIN ENROLL ON (STUDENT.Sno = ENROLL.Sno)
WHERE ENROLL.Cno = 'C413';

